cat > backend/model/crm_leads.json <<'EOF'
{
  "modules": {
    "crm": {
      "features": {
        "crm_leads": {
          "requirement": {
            "statement": "销售录入、更新并推进自己名下线索（new→contacted→qualified→converted/lost），线索创建幂等；负责人对 qualified 线索发起转化：金额<100000 直接转化并创建只读客户，≥100000 进入总监审批流，通过时同事务转化并创建客户，拒绝时回到 qualified 并记录原因；审批结果站内通知发起人；所有状态变化与审批留审计。",
            "acceptance": [
              "相同幂等键重复创建只产生一条线索。",
              "非负责人对线索的写入被拒绝且状态不变。",
              "小额转化只创建一个只读客户，重放不产生第二个客户。",
              "大额转化生成审批任务，总监通过后线索 converted 且客户创建在同一事务，发起人收到通知；拒绝后线索回到 qualified 并记录拒绝原因且不创建客户。"
            ]
          },
          "objects": {
            "lead": {
              "description": "销售线索",
              "fields": {
                "company_name": "text!",
                "contact_name": "text",
                "contact_phone": "phone",
                "expected_amount": "currency!=0;precision=19;scale=2;currency=CNY;rounding=half_even",
                "source": "select![website:官网|exhibition:展会|referral:转介绍|outbound_call:外呼]",
                "status": "select![new:新建|contacted:已联系|qualified:已合格|converted:已转化|lost:已流失]=new",
                "sales_user_id": "user!",
                "department_org_id": "text!",
                "status_changed_at": "datetime!",
                "next_followup_at": "datetime",
                "lost_reason": "long_text",
                "rejection_reason": "long_text",
                "converted_at": "datetime"
              }
            },
            "customer": {
              "description": "成交客户（只读，由转化流程创建）",
              "fields": {
                "company_name": "text!",
                "contact_name": "text",
                "contact_phone": "phone",
                "amount": "currency!=0;precision=19;scale=2;currency=CNY;rounding=half_even",
                "source": "select![website:官网|exhibition:展会|referral:转介绍|outbound_call:外呼]",
                "lead_id": "relation!->lead;cardinality=one_to_one",
                "sales_user_id": "user!",
                "converted_at": "datetime!"
              }
            },
            "conversion_approval": {
              "description": "大额线索转化审批请求",
              "fields": {
                "lead_id": "relation!->lead",
                "requester_user_id": "user!",
                "expected_amount": "currency!=0;precision=19;scale=2;currency=CNY;rounding=half_even",
                "status": "select![pending:待审批|approved:已通过|rejected:已拒绝]=pending",
                "decided_by": "user",
                "decided_at": "datetime",
                "rejection_reason": "long_text"
              }
            },
            "lead_audit": {
              "description": "线索状态变化与转化审批审计（仅追加）",
              "fields": {
                "lead_id": "relation!->lead",
                "event": "select![created:创建|revised:更新|status_changed:状态变化|conversion_requested:发起审批|converted:已转化|approval_approved:审批通过|approval_rejected:审批拒绝|followup_reminded:跟进提醒]",
                "from_status": "text",
                "to_status": "text",
                "actor_user_id": "user",
                "reason": "long_text",
                "occurred_at": "datetime!"
              }
            }
          },
          "actions": {
            "lead.register": {
              "kind": "object_operation",
              "input": {
                "company_name": "text!",
                "contact_name": "text",
                "contact_phone": "phone",
                "expected_amount": "currency!=0;precision=19;scale=2;currency=CNY;rounding=half_even",
                "source": "select![website:官网|exhibition:展会|referral:转介绍|outbound_call:外呼]"
              },
              "handler": {
                "reason": "创建线索必须从可信主体派生负责人与部门、初始化状态时间并在同一事务写入审计",
                "access": {
                  "lead": ["create"],
                  "lead_audit": ["create"]
                }
              }
            },
            "lead.revise": {
              "kind": "record_operation",
              "input": {
                "contact_name": "text",
                "contact_phone": "phone",
                "expected_amount": "currency;precision=19;scale=2;currency=CNY;rounding=half_even",
                "source": "select![website:官网|exhibition:展会|referral:转介绍|outbound_call:外呼]"
              },
              "preconditions": ["status not in converted,lost"],
              "handler": {
                "reason": "负责人更新联系人/电话/预计金额/来源时必须校验非终态并原子写入审计",
                "access": {
                  "lead": ["get_for_update", "conditional_update"],
                  "lead_audit": ["create"]
                }
              }
            },
            "lead.advance": {
              "kind": "record_operation",
              "input": {
                "target_status": "select![contacted:已联系|qualified:已合格|lost:已流失]",
                "reason": "long_text"
              },
              "preconditions": ["status not in converted,lost"],
              "handler": {
                "reason": "状态推进必须沿定义转换校验，进入 contacted 时计算并持久化 status_changed_at 与 next_followup_at，离开时清空，并原子写入审计",
                "access": {
                  "lead": ["get_for_update", "conditional_update"],
                  "lead_audit": ["create"]
                }
              }
            },
            "lead.convert": {
              "kind": "record_operation",
              "output": {
                "outcome": "select![converted:已转化|approval_pending:待审批]"
              },
              "preconditions": ["status == qualified"],
              "handler": {
                "reason": "转化必须按金额阈值分流：小额同事务转化并创建唯一客户，大额创建审批请求启动审批流，重复发起不产生第二个客户或审批",
                "access": {
                  "lead": ["get_for_update", "conditional_update"],
                  "customer": ["create", "exists"],
                  "conversion_approval": ["create", "list"],
                  "lead_audit": ["create"]
                }
              }
            },
            "conversion_approval.finalize_approved": {
              "kind": "record_operation",
              "output": {
                "customer_created": "boolean"
              },
              "handler": {
                "reason": "审批通过必须在同一事务中把线索置为 converted、创建唯一客户、记录审批结果与审计并向发起人发出通知意图",
                "access": {
                  "conversion_approval": ["get_for_update", "conditional_update"],
                  "lead": ["get_for_update", "conditional_update"],
                  "customer": ["create", "exists"],
                  "lead_audit": ["create"]
                },
                "notification_event_types": ["conversion_approval.approved"]
              }
            },
            "conversion_approval.finalize_rejected": {
              "kind": "record_operation",
              "input": {
                "rejection_reason": "long_text"
              },
              "handler": {
                "reason": "审批拒绝必须在同一事务中让线索保持 qualified、记录拒绝原因与审计并向发起人发出通知意图",
                "access": {
                  "conversion_approval": ["get_for_update", "conditional_update"],
                  "lead": ["get_for_update", "conditional_update"],
                  "lead_audit": ["create"]
                },
                "notification_event_types": ["conversion_approval.rejected"]
              }
            }
          },
          "state_machines": {
            "lead_lifecycle": {
              "object_key": "lead",
              "field_key": "status",
              "states": ["new", "contacted", "qualified", "converted", "lost"],
              "terminal_states": ["converted", "lost"],
              "transitions": {
                "new->contacted": "lead.advance",
                "contacted->qualified": "lead.advance",
                "qualified->converted": "lead.convert",
                "qualified->lost": "lead.advance"
              }
            }
          },
          "workflows": {
            "conversion_approval_flow": {
              "enabled": true,
              "run_as": "crm_workflow_service",
              "trigger": {"type": "record_created"},
              "action": {"type": "workflow_graph"},
              "trigger_contract": {"type": "record_created", "object_key": "conversion_approval"},
              "graph": {
                "nodes": {
                  "requested": {"type": "trigger"},
                  "director_approval": {
                    "type": "approval",
                    "contract": {
                      "approval": {
                        "title": "大额线索转化审批",
                        "mode": "any",
                        "empty_assignee_policy": "fail",
                        "resolvers": [{"type": "role", "role_key": "sales_director"}]
                      }
                    }
                  },
                  "finalize_approved": {
                    "type": "action",
                    "contract": {
                      "action": {"action_key": "conversion_approval.finalize_approved", "on_error": "fail"}
                    }
                  },
                  "finalize_rejected": {
                    "type": "action",
                    "contract": {
                      "action": {
                        "action_key": "conversion_approval.finalize_rejected",
                        "input": {"rejection_reason": "$workflow.approval_comment"},
                        "on_error": "fail"
                      }
                    }
                  }
                },
                "edges": {
                  "requested_approval": {"source": "requested", "target": "director_approval"},
                  "approval_approved": {"source": "director_approval", "target": "finalize_approved", "branch": "approved"},
                  "approval_rejected": {"source": "director_approval", "target": "finalize_rejected", "branch": "rejected"}
                }
              }
            }
          },
          "notification_event_types": {
            "conversion_approval.approved": {
              "source": "project",
              "category": "business",
              "default_severity": "info",
              "mandatory_in_app": true,
              "template_key": "conversion_approval_approved",
              "default_locale": "zh_CN",
              "locales": {
                "zh_CN": {
                  "title": "线索转化审批已通过",
                  "body": "线索「{{company_name}}」的大额转化审批已通过，客户已创建。",
                  "action_labels": {"open_lead": "查看线索"}
                }
              },
              "variables": {"company_name": "text!"},
              "actions": {
                "open_lead": {"resource_type": "project_record", "route_key": "business.leads.my"}
              }
            },
            "conversion_approval.rejected": {
              "source": "project",
              "category": "business",
              "default_severity": "warning",
              "mandatory_in_app": true,
              "template_key": "conversion_approval_rejected",
              "default_locale": "zh_CN",
              "locales": {
                "zh_CN": {
                  "title": "线索转化审批被拒绝",
                  "body": "线索「{{company_name}}」的大额转化审批被拒绝：{{rejection_reason}}。线索已回到已合格状态。",
                  "action_labels": {"open_lead": "查看线索"}
                }
              },
              "variables": {"company_name": "text!", "rejection_reason": "text!"},
              "actions": {
                "open_lead": {"resource_type": "project_record", "route_key": "business.leads.my"}
              }
            }
          }
        }
      }
    }
  }
}
