cat > backend/model/crm_followup.json <<'EOF'
{
  "modules": {
    "crm": {
      "features": {
        "crm_followup": {
          "requirement": {
            "statement": "线索进入 contacted 时持久化 status_changed_at 与 next_followup_at（按部署时区与工作日日历计算为超过 7 天后的首个工作日早晨）；Workflow 监听 next_followup_at 变化，条件 status==contacted 时以 one-shot timer 消费该精确时间并在到期后执行提醒 Action；提醒按（线索，本地日期）唯一去重，仍为 contacted 时推进到下一工作日早晨；离开 contacted 清空 next_followup_at，旧 timer 到点无副作用。",
            "acceptance": [
              "进入 contacted 后两个时间字段真实持久化且没有立即提醒。",
              "到期后 Runtime record_timer 恢复流程，提醒幂等写入并推进下一工作日 due。",
              "状态退出后旧 timer 到点无副作用。"
            ]
          },
          "objects": {
            "followup_reminder": {
              "description": "线索跟进到期提醒记录（每条线索每个本地日期最多一条）",
              "fields": {
                "lead_id": "relation!->lead",
                "reminder_local_date": "date!",
                "recipient_user_id": "user!",
                "due_at": "datetime!"
              },
              "validations": {
                "lead_reminder_local_date": {
                  "object_key": "followup_reminder",
                  "type": "composite_unique",
                  "fields": ["lead_id", "reminder_local_date"]
                }
              }
            }
          },
          "actions": {
            "lead.followup_due": {
              "kind": "record_operation",
              "output": {
                "outcome": "select![reminded:已提醒|already_reminded:已去重|stale:已失效]"
              },
              "handler": {
                "reason": "到期 Action 必须重读当前状态：仍为 contacted 时按本地日期幂等写入提醒、发出通知意图并推进 next_followup_at 到下一工作日早晨；否则无副作用",
                "access": {
                  "lead": ["get_for_update", "conditional_update"],
                  "followup_reminder": ["create", "exists"],
                  "lead_audit": ["create"]
                },
                "notification_event_types": ["lead.followup_reminder"]
              }
            }
          },
          "workflows": {
            "lead_followup_flow": {
              "enabled": true,
              "run_as": "crm_workflow_service",
              "trigger": {"type": "field_changed"},
              "action": {"type": "workflow_graph"},
              "trigger_contract": {"type": "field_changed", "object_key": "lead", "field_key": "next_followup_at"},
              "graph": {
                "nodes": {
                  "due_changed": {"type": "trigger"},
                  "still_contacted": {
                    "type": "condition",
                    "contract": {
                      "condition": {"type": "field_equals", "field": "status", "value": "contacted"}
                    }
                  },
                  "wait_due": {
                    "type": "timer",
                    "contract": {
                      "timer": {
                        "timer_key": "followup_due",
                        "purpose": "线索跟进到期提醒",
                        "source_field": "next_followup_at",
                        "timezone": "Asia/Shanghai"
                      }
                    }
                  },
                  "remind": {
                    "type": "action",
                    "contract": {
                      "action": {"action_key": "lead.followup_due", "on_error": "fail"}
                    }
                  }
                },
                "edges": {
                  "changed_check": {"source": "due_changed", "target": "still_contacted"},
                  "check_true_wait": {"source": "still_contacted", "target": "wait_due", "branch": "true"},
                  "wait_remind": {"source": "wait_due", "target": "remind"}
                }
              }
            }
          },
          "notification_event_types": {
            "lead.followup_reminder": {
              "source": "project",
              "category": "business",
              "default_severity": "info",
              "mandatory_in_app": true,
              "template_key": "lead_followup_reminder",
              "default_locale": "zh_CN",
              "locales": {
                "zh_CN": {
                  "title": "线索跟进提醒",
                  "body": "线索「{{company_name}}」已联系超过 7 天，请在 {{reminder_date}} 跟进。",
                  "action_labels": {"open_lead": "查看线索"}
                }
              },
              "variables": {"company_name": "text!", "reminder_date": "date!"},
              "actions": {
                "open_lead": {"resource_type": "project_record", "route_key": "business.leads.my"}
              }
            }
          }
        }
      }
    }
  }
}
EOF
