cat > backend/reports/crm_funnel.sql <<'EOF'
SELECT l.`status` AS status,
       COUNT(l.`id`) AS lead_count,
       SUM(l.`expected_amount`) AS expected_amount_total
FROM `lead` l
GROUP BY l.`status`
ORDER BY l.`status`
LIMIT 100
EOF
cat > backend/reports/crm_lead_export.sql <<'EOF'
SELECT l.`company_name` AS company_name,
       l.`contact_name` AS contact_name,
       l.`contact_phone` AS contact_phone,
       l.`expected_amount` AS expected_amount,
       l.`source` AS source,
       l.`status` AS status,
       l.`sales_user_id` AS sales_user_id,
       l.`department_org_id` AS department_org_id,
       l.`status_changed_at` AS status_changed_at
FROM `lead` l
ORDER BY l.`company_name`, l.`status_changed_at`
LIMIT 5000
EOF
